<!--
 * 任务历史版本管理（列表页）
 *
 * @path apps\cronjob-web\src\views\job-history\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务历史版本管理（P1-配置版本闭环）
 * <p>消费后端契约 jobHistory.ts（auto-generated by bash/gen-contract.py）：
 * versions 获取任务版本列表、detail 获取历史详情、rollback 回滚到指定版本、compare 版本对比。
 * 布局：顶部筛选栏（任务标识）+ 版本列表 + 详情抽屉 + 对比弹窗。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { YdBadge, YdButtonBase, YdSelectBase, YdSelectContentBase, YdSelectItemBase, YdSelectTriggerBase, YdSelectValueBase, YdSheet, YdSheetContent, YdForm, YdFormItem } from '@ydsz-core/ydsz-ui';
import { h, onMounted, ref } from 'vue';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { compare, detail, rollback, versions } from '#/api/jobHistory';
import type { JobHistoryVO } from '#/api/models';

import { createLogger } from '@ydsz-core/shared/utils';

const logger = createLogger('cronjob-job-history');

defineOptions({ name: 'JobHistoryManagement' });

// ==================== 数据 ====================

/** 当前过滤的任务 ID */
const currentJobId = ref<string>('');
/** 全量数据（versions API 返回不分页） */
const gridData = ref<JobHistoryVO[]>([]);
/** 加载中 */
const isLoading = ref(false);

// ==================== 详情抽屉 ====================

/** 详情抽屉可见性 */
const isDetailVisible = ref(false);
/** 当前查看的历史版本 */
const detailRecord = ref<JobHistoryVO | null>(null);

/** 打开详情抽屉 */
async function handleViewDetail(row: JobHistoryVO): Promise<void> {
  if (!row.jobId || row.version === undefined) return;
  isDetailVisible.value = true;
  try {
    const result = await detail({ jobId: row.jobId, version: row.version });
    detailRecord.value = result;
  } catch {
    logger.warn('加载历史详情失败', row.jobId);
    isDetailVisible.value = false;
  }
}

// ==================== 回滚 ====================

/** 执行回滚到指定版本 */
async function handleRollback(row: JobHistoryVO): Promise<void> {
  if (!row.jobId || row.version === undefined) return;
  try {
    await YdConfirm(
      `确定回滚「${row.jobName ?? row.jobKey}」到版本 v${row.version} 吗？`,
      '回滚确认',
      { type: 'warning' },
    );
  } catch {
    logger.warn('用户取消回滚', row.jobId);
    return;
  }
  try {
    await rollback({ jobId: row.jobId, version: row.version });
    showToast.success('回滚成功');
    gridApi.query();
  } catch {
    logger.warn('回滚失败', row.jobId);
  }
}

// ==================== 版本对比 ====================

/** 对比弹窗可见性 */
const isCompareVisible = ref(false);
/** 对比左侧版本号 */
const compareV1 = ref<number | undefined>(undefined);
/** 对比右侧版本号 */
const compareV2 = ref<number | undefined>(undefined);
/** 对比任务 ID */
const compareJobId = ref<string>('');
/** 对比结果 */
const compareResult = ref<Record<string, Record<string, unknown>>[]>([]);

/** 版本号列表（用于筛选框） */
const versionOptions = ref<{ label: string; value: number }[]>([]);

/** 打开对比弹窗 */
function openCompareDialog(jobId: string): void {
  compareJobId.value = jobId;
  compareV1.value = undefined;
  compareV2.value = undefined;
  compareResult.value = [];
  versionOptions.value = gridData.value
    .filter((item) => item.jobId === jobId && item.version !== undefined)
    .map((item) => ({ label: `v${item.version}`, value: item.version as number }));
  isCompareVisible.value = true;
}

/** 执行对比查询 */
async function handleCompare(): Promise<void> {
  if (!compareJobId.value || compareV1.value === undefined || compareV2.value === undefined) {
    showToast.warning('请选择需要对比的两个版本');
    return;
  }
  try {
    const result = await compare({
      jobId: compareJobId.value,
      v1: compareV1.value,
      v2: compareV2.value,
    });
    compareResult.value = result ?? [];
    showToast.success('对比完成');
  } catch {
    logger.warn('版本对比失败', compareJobId.value);
  }
}

// ==================== 工具方法 ====================

/** 判断是否为 CREATE 类型 */
function isCreate(row: JobHistoryVO): boolean {
  return row.changeType === 'CREATE';
}

/** 判断是否为 DELETE 类型 */
function isDelete(row: JobHistoryVO): boolean {
  return row.changeType === 'DELETE';
}

/** 变更类型标签颜色映射 */
function changeTypeTagType(row: JobHistoryVO): 'success' | 'warning' | 'danger' {
  if (isCreate(row)) return 'success';
  if (isDelete(row)) return 'danger';
  return 'warning';
}

/** 变更类型中文映射 */
function translateChangeType(changeType?: string): string {
  const map: Record<string, string> = {
    CREATE: '创建',
    UPDATE: '更新',
    DELETE: '删除',
  };
  return map[changeType ?? ''] ?? changeType ?? '-';
}

// ==================== 数据加载 ====================

/** 加载版本数据 */
async function loadVersions(jobId?: string): Promise<JobHistoryVO[]> {
  try {
    isLoading.value = true;
    const result = await versions({ jobId });
    gridData.value = result ?? [];
    return gridData.value;
  } catch {
    logger.warn('加载版本列表失败');
    gridData.value = [];
    return [];
  } finally {
    isLoading.value = false;
  }
}

// ==================== Vxe 表格 ====================

const gridOptions: VxeTableGridOptions<JobHistoryVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'jobName', title: '任务名称', width: 160 },
    { field: 'jobKey', title: '任务标识', width: 140 },
    {
      field: 'version',
      title: '版本号',
      width: 90,
      formatter: ({ cellValue }) => `v${cellValue ?? '-'}`,
    },
    {
      field: 'changeType',
      title: '变更类型',
      width: 90,
      slots: {
        default: ({ row }) => {
          const item = row as JobHistoryVO;
          return h(YdBadge, { variant: changeTypeTagType(item), size: 'sm' }, () =>
            translateChangeType(item.changeType),
          );
        },
      },
    },
    { field: 'changeRemark', title: '变更说明', minWidth: 160 },
    { field: 'cronExpression', title: 'Cron', width: 140 },
    { field: 'handler', title: '执行器', width: 140 },
    { field: 'changedBy', title: '修改人', width: 100 },
    { field: 'changedAt', title: '修改时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) => {
          const item = row as JobHistoryVO;
          return h('div', { class: 'flex gap-1' }, [
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => handleViewDetail(item) },
              () => '详情',
            ),
            h(
              YdButtonBase,
              { size: 'sm', variant: 'link', onClick: () => openCompareDialog(item.jobId ?? '') },
              () => '对比',
            ),
            h(
              YdButtonBase,
              {
                size: 'sm',
                variant: 'link',
                disabled: isDelete(item),
                onClick: () => handleRollback(item),
              },
              () => '回滚',
            ),
          ]);
        },
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async () => {
        const items = await loadVersions(currentJobId.value || undefined);
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'keyword',
        title: '任务标识',
        itemRender: { name: 'YdInput', props: { placeholder: '任务 ID / Key' } },
      },
    ],
  },
};

const [Grid, gridApi] = useYDSZVxeGrid({ gridOptions });

// 查询时同步更新 currentJobId
const originalQuery = gridApi.query.bind(gridApi);
gridApi.query = async (formValues?: Record<string, unknown>): Promise<void> => {
  if (formValues && typeof formValues.keyword === 'string') {
    currentJobId.value = formValues.keyword;
  }
  await originalQuery(formValues);
};

onMounted(() => {
  loadVersions();
});
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="任务历史版本" />

    <!-- 详情历史 YdSheet -->
    <YdSheet v-model:open="isDetailVisible">
      <YdSheetContent side="right" class="w-[600px]">
      <template v-if="detailRecord">
        <YdDescriptions :column="2" border size="small">
          <YdDescriptionsItem label="任务名称">{{ detailRecord.jobName ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="任务标识">{{ detailRecord.jobKey ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="版本号">v{{ detailRecord.version ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="变更类型">
            <YdBadge :variant="changeTypeTagType(detailRecord)" size="sm">
              {{ translateChangeType(detailRecord.changeType) }}
            </YdBadge>
          </YdDescriptionsItem>
          <YdDescriptionsItem label="变更说明" :span="2">
            {{ detailRecord.changeRemark ?? '-' }}
          </YdDescriptionsItem>
          <YdDescriptionsItem label="Cron">{{ detailRecord.cronExpression ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="执行器">{{ detailRecord.handler ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="修改人">{{ detailRecord.changedBy ?? '-' }}</YdDescriptionsItem>
          <YdDescriptionsItem label="修改时间">{{ detailRecord.changedAt ?? '-' }}</YdDescriptionsItem>
        </YdDescriptions>
        <YdDescriptions
          v-if="detailRecord.snapshot"
          :column="1"
          border
          size="small"
          class="mt-3"
        >
          <YdDescriptionsItem label="版本快照">
            <pre class="max-h-60 overflow-auto whitespace-pre-wrap break-all text-xs">{{ detailRecord.snapshot }}</pre>
          </YdDescriptionsItem>
        </YdDescriptions>
      </template>
      </YdSheetContent>
    </YdSheet>

    <!-- 版本对比 YdSheet -->
    <YdSheet v-model:open="isCompareVisible">
      <YdSheetContent side="right" class="w-[700px]">
        <div class="mb-2 text-base font-semibold">版本对比</div>
      <YdForm label-width="80px" class="mb-3">
        <YdFormItem label="版本 A">
          <YdSelectBase v-model="compareV1">
            <YdSelectTriggerBase class="w-[180px]" placeholder="选择版本" />
            <YdSelectContentBase>
              <YdSelectItemBase
                v-for="opt in versionOptions"
                :key="opt.value"
                :value="String(opt.value)"
              >
                {{ opt.label }}
              </YdSelectItemBase>
            </YdSelectContentBase>
          </YdSelectBase>
        </YdFormItem>
        <YdFormItem label="版本 B">
          <YdSelectBase v-model="compareV2">
            <YdSelectTriggerBase class="w-[180px]" placeholder="选择版本" />
            <YdSelectContentBase>
              <YdSelectItemBase
                v-for="opt in versionOptions"
                :key="opt.value"
                :value="String(opt.value)"
              >
                {{ opt.label }}
              </YdSelectItemBase>
            </YdSelectContentBase>
          </YdSelectBase>
        </YdFormItem>
        <YdFormItem>
          <YdButtonBase @click="handleCompare">开始对比</YdButtonBase>
        </YdFormItem>
      </YdForm>
      <div v-if="compareResult.length > 0" class="space-y-2">
        <div v-for="(diff, idx) in compareResult" :key="idx" class="rounded border border-gray-200 p-3">
          <div v-for="(val, field) in diff" :key="field" class="grid grid-cols-3 gap-2 text-sm">
            <span class="font-medium text-gray-600">{{ field }}</span>
            <span class="text-red-600 line-through">{{ String(val ?? '-') }}</span>
            <span class="text-green-600">{{ String(val ?? '-') }}</span>
          </div>
        </div>
      </div>
      </YdSheetContent>
    </YdSheet>
  </Page>
</template>
